import math

def count_nonzero_pixels(region, bg=0):
    return sum(sum(1 for cell in row if cell != bg) for row in region)

def count_nonzero_cols(region):
    ncols = len(region[0]) if region else 0
    count = 0
    for c in range(ncols):
        for r in range(len(region)):
            if region[r][c] != 0:
                count += 1
                break
    return count

